<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * `myat_projects` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property string|null $Name
 * @property string|null $Emoji
 * @property string|null $Color
 * @property string|null $Description
 * @property int|null $Archived
 * @property int|null $Sort
 * @property string|null $CreatedBy
 * @property Carbon|null $CreatedAt
 */
class MyatProject extends Model
{
    protected $table = 'myat_projects';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'Archived' => 'integer',
            'Sort' => 'integer',
            'CreatedAt' => 'datetime',
        ];
    }

    /** Text columns PHPRunner-style: blank is '' (the table's defaults), never NULL. */
    public const BLANK_AS_EMPTY_STRING = ['Name', 'Emoji', 'CreatedBy'];

    public function tasks(): HasMany
    {
        return $this->hasMany(MyatTask::class, 'ProjectID', 'ID');
    }
}
